frappe.ui.form.on('Sales Invoice', {
    refresh: function(frm) {
        // Read-only Company display next to the document title (where Invoice No. shows)
        if (frm.doc.company) {
            frm.page.set_title_sub(__('Company') + ': ' + frm.doc.company);
        }

        // Print format buttons — always visible for GPP company
        if (frm.doc.company === 'Gajanand Paper Print' && !frm.doc.__islocal) {
            frm.add_custom_button(__('Print Delivery Challan'), function() {
                var url = '/printview?doctype=Sales%20Invoice&name=' + encodeURIComponent(frm.doc.name)
                    + '&format=GPP%20Delivery%20Challan&no_letterhead=0';
                window.open(url, '_blank');
            }, __('Print'));

            frm.add_custom_button(__('Print Sales Invoice'), function() {
                var url = '/printview?doctype=Sales%20Invoice&name=' + encodeURIComponent(frm.doc.name)
                    + '&format=GPP%20Sales%20Invoice&no_letterhead=0';
                window.open(url, '_blank');
            }, __('Print'));
        }

        if (frm.doc.docstatus === 1) {  // Only show when submitted

        // Add "Send Email" under group "Send Invoice"
        frm.add_custom_button(__('Send Whatsapp'), function() {
            frappe.show_progress('Sending Message with Invoice PDF', 0, 100, 'In Progress...');
                frappe.call({
                    method: 'erpnext.accounts.doctype.sales_invoice.sales_invoice.send_invoice_whatsapp',
                    args: {
                      invoice_name: frm.doc.name
                    },
                    callback: function(r) {
                        frappe.hide_progress();
                        frappe.msgprint("Whatsapp Message Sent Successfully")
                    }
                });
        }, __("Send Invoice"));  // <-- group name

        // Add "Send WhatsApp" under same group "Send Invoice"
        frm.add_custom_button(__('Send Email'), function() {
            frappe.show_progress('Sending Email with Invoice PDF', 0, 100, 'In Progress...');
                frappe.call({
                    method: 'erpnext.accounts.doctype.sales_invoice.sales_invoice.send_invoice_email',
                    args: {
                      docId: frm.doc.name

                    },
                    callback: function(r) {
                        frappe.hide_progress();

                    }
                });



        }, __("Send Invoice"));  // <-- same group name

    }   
    }
});


frappe.ui.form.on('Sales Invoice', {
    customer: function(frm) {
        if (frm.doc.customer && frm.doc.company) {
            frappe.call({
                method: "frappe.client.get_value",
                args: {
                    doctype: "Customer",
                    filters: {
                        name: frm.doc.customer
                    },
                    fieldname: ["credit_days"]
                },
                callback: function(r) {
                    if (r.message && r.message.credit_days) {
                        let posting_date = frappe.datetime.str_to_obj(frm.doc.posting_date);
                        let due_date = frappe.datetime.add_days(posting_date, r.message.credit_days);
                        frm.set_value("due_date", frappe.datetime.obj_to_str(due_date));
                    }
                }
            });
        }
    }
});


