        if (frm.doc.docstatus === 1 && !frm.doc.is_return) {

            frm.add_custom_button(__("📋 Quick Debit Note"), function () {
                gj_show_debit_note_dialog(frm);
            }, __("Create"));

        }
    }

});

// ─────────────────────────────────────────────────────────────
// DIALOG
// ─────────────────────────────────────────────────────────────
function gj_show_debit_note_dialog(frm) {

    var orig_date    = frm.doc.posting_date;
    var orig_total   = flt(frm.doc.grand_total);
    var orig_taxable = flt(frm.doc.net_total);

    // Calculate GST rate from tax rows
    var gst_rate = 0;
    (frm.doc.taxes || []).forEach(function(t) {
        gst_rate += flt(t.rate);
    });

    var d = new frappe.ui.Dialog({
        title: "📋 Quick Debit Note — Rate Difference",
        size:  "large",
        fields: [
            // ── Reference ─────────────────────────────────
            {
                fieldtype: "Section Break",
                label:     "Original Invoice Reference"
            },
            {
                fieldtype: "HTML",
                fieldname: "orig_info",
                options: `
                <div style="background:#f0fdf4;border:1px solid #bbf7d0;border-radius:8px;
                            padding:10px 14px;font-size:12px;margin-bottom:4px">
                    <div style="display:flex;gap:24px;flex-wrap:wrap">
                        <div>
                            <div style="font-size:10px;color:#065f46;font-weight:700;
                                        text-transform:uppercase;letter-spacing:0.5px">Invoice</div>
                            <div style="font-weight:700;font-size:13px">${frm.doc.name}</div>
                        </div>
                        <div>
                            <div style="font-size:10px;color:#065f46;font-weight:700;
                                        text-transform:uppercase;letter-spacing:0.5px">Supplier</div>
                            <div style="font-weight:700">${frm.doc.supplier_name || frm.doc.supplier}</div>
                        </div>
                        <div>
                            <div style="font-size:10px;color:#065f46;font-weight:700;
                                        text-transform:uppercase;letter-spacing:0.5px">Invoice Date</div>
                            <div style="font-weight:700;color:#059669">${orig_date}</div>
                        </div>
                        <div>
                            <div style="font-size:10px;color:#065f46;font-weight:700;
                                        text-transform:uppercase;letter-spacing:0.5px">Taxable Amt</div>
                            <div style="font-weight:700">₹ ${orig_taxable.toFixed(2)}</div>
                        </div>
                        <div>
                            <div style="font-size:10px;color:#065f46;font-weight:700;
                                        text-transform:uppercase;letter-spacing:0.5px">Grand Total</div>
                            <div style="font-weight:700">₹ ${orig_total.toFixed(2)}</div>
                        </div>
                        <div>
                            <div style="font-size:10px;color:#065f46;font-weight:700;
                                        text-transform:uppercase;letter-spacing:0.5px">GST Rate</div>
                            <div style="font-weight:700">${gst_rate}%</div>
                        </div>
                    </div>
                </div>`
            },

            // ── Debit Note Details ─────────────────────────
            {
                fieldtype: "Section Break",
                label:     "Debit Note Details"
            },
            {
                fieldtype:    "Date",
                fieldname:    "posting_date",
                label:        "Debit Note Date",
                reqd:         1,
                default:      frappe.datetime.get_today(),
                description:  "Date of debit note — original invoice date shown above for reference"
            },
            { fieldtype: "Column Break" },
            {
                fieldtype:   "Currency",
                fieldname:   "debit_amount",
                label:       "Debit Amount (Taxable, excl. GST) ₹",
                reqd:        1,
                description: "Amount before GST — GST will be auto-calculated at " + gst_rate + "%"
            },

            // ── Live Preview ───────────────────────────────
            {
                fieldtype: "Section Break",
                label:     "Amount Breakdown"
            },
            {
                fieldtype: "HTML",
                fieldname: "amount_preview",
                options:   `<div id="gj-dn-preview" style="color:#9ca3af;font-size:12px;padding:4px 0">
                    Enter amount above to see breakdown
                </div>`
            },

            // ── Reason ────────────────────────────────────
            {
                fieldtype: "Section Break",
                label:     "Reason"
            },
            {
                fieldtype:   "Small Text",
                fieldname:   "reason",
                label:       "Reason for Debit Note",
                reqd:        1,
                placeholder: "e.g. Rate charged higher than agreed — debit note for difference"
            }
        ],
        primary_action_label: "✅ Create & Submit Debit Note",
        primary_action: function (values) {
            gj_create_debit_note(frm, d, values, gst_rate);
        }
    });

    d.show();

    // Live amount preview
    d.$wrapper.on("input change",
        "[data-fieldname='debit_amount'] input",
        function () {
            gj_update_dn_preview(d, gst_rate);
        }
    );
}

// ─────────────────────────────────────────────────────────────
// LIVE PREVIEW
// ─────────────────────────────────────────────────────────────
function gj_update_dn_preview(d, gst_rate) {
    var taxable = flt(d.$wrapper.find("[data-fieldname='debit_amount'] input").val()) || 0;
    if (taxable <= 0) return;

    var half_rate  = gst_rate / 2;
    var cgst       = flt(taxable * half_rate / 100, 2);
    var sgst       = flt(taxable * half_rate / 100, 2);
    var total_gst  = flt(cgst + sgst, 2);
    var grand      = flt(taxable + total_gst, 2);

    d.$wrapper.find("#gj-dn-preview").html(`
    <div style="display:flex;gap:16px;flex-wrap:wrap;
                background:#fef9c3;border:1px solid #fde68a;
                border-radius:8px;padding:10px 14px">
        <div>
            <div style="font-size:9px;color:#92400e;font-weight:700;text-transform:uppercase">Taxable</div>
            <div style="font-size:14px;font-weight:700">₹ ${taxable.toFixed(2)}</div>
        </div>
        <div>
            <div style="font-size:9px;color:#92400e;font-weight:700;text-transform:uppercase">
                CGST @ ${half_rate}%
            </div>
            <div style="font-size:14px;font-weight:700">₹ ${cgst.toFixed(2)}</div>
        </div>
        <div>
            <div style="font-size:9px;color:#92400e;font-weight:700;text-transform:uppercase">
                SGST @ ${half_rate}%
            </div>
            <div style="font-size:14px;font-weight:700">₹ ${sgst.toFixed(2)}</div>
        </div>
        <div>
            <div style="font-size:9px;color:#92400e;font-weight:700;text-transform:uppercase">
                Grand Total
            </div>
            <div style="font-size:16px;font-weight:900;color:#92400e">₹ ${grand.toFixed(2)}</div>
        </div>
    </div>
    `);
}

// ─────────────────────────────────────────────────────────────
// CREATE DEBIT NOTE — calls server API
// ─────────────────────────────────────────────────────────────
function gj_create_debit_note(frm, d, values, gst_rate) {

    if (flt(values.debit_amount) <= 0) {
        frappe.msgprint({
            title: "Invalid Amount",
            message: "Debit amount must be greater than zero.",
            indicator: "orange"
        });
        return;
    }

    d.disable_primary_action();
    frappe.show_progress("Creating Debit Note...", 20, 100);

    frappe.call({
        method: "erpnext.accounts.doctype.purchase_invoice.purchase_invoice.create_quick_debit_note",
        args: {
            return_against: frm.doc.name,
            posting_date:   values.posting_date,
            debit_amount:   values.debit_amount,
            reason:         values.reason
        },
        callback: function (r) {
            frappe.show_progress("", 100, 100);

            if (r.exc || !r.message) {
                d.enable_primary_action();
                frappe.msgprint({
                    title:     "Error",
                    message:   "Could not create Debit Note. Check console for details.",
                    indicator: "red"
                });
                return;
            }

            var dn_name = r.message;
            d.hide();

            frappe.show_alert({
                message:   "✅ Debit Note <b>" + dn_name + "</b> created and submitted",
                indicator: "green"
            }, 8);


        }
    });
}

