// ── Live GST Preview ──────────────────────────────────────────
function update_preview(d) {
	var amount   = flt(d.get_value('credit_amount'));
	var template = d.get_value('tax_template');

	if (!amount || !template) {
		$('#gj-cn-preview').html('<span style="color:#6b7a99">Enter amount to see GST preview</span>');
		return;
	}

	frappe.db.get_list('Sales Taxes and Charges', {
		filters: [['parent', '=', template]],
		fields: ['description', 'rate', 'account_head'],
		limit: 10
	}).then(function(taxes) {
		var total_tax = 0;
		var rows = taxes.map(function(t) {
			var tax_amt = flt((amount * t.rate) / 100, 2);
			total_tax += tax_amt;
			return '<tr>'
				+ '<td style="padding:4px 8px;color:#374151">' + (t.account_head || t.description || '') + '</td>'
				+ '<td style="padding:4px 8px;text-align:right">' + t.rate + '%</td>'
				+ '<td style="padding:4px 8px;font-weight:700;color:#1d4ed8;text-align:right">₹' + fmt_cur(tax_amt) + '</td>'
				+ '</tr>';
		}).join('');

		$('#gj-cn-preview').html(
			'<table style="width:100%;border-collapse:collapse">'
			+ '<tr style="border-bottom:1px solid #e2e8f4">'
			+ '<td style="padding:4px 8px;color:#6b7a99">Base Amount</td>'
			+ '<td colspan="2" style="padding:4px 8px;font-weight:700;text-align:right">₹' + fmt_cur(amount) + '</td>'
			+ '</tr>'
			+ rows
			+ '<tr style="border-top:2px solid #dbeafe;background:#eff6ff">'
			+ '<td style="padding:6px 8px;font-weight:800;color:#1a2340">Total Credit Note</td>'
			+ '<td colspan="2" style="padding:6px 8px;font-weight:800;color:#16a34a;font-size:14px;text-align:right">₹'
			+ fmt_cur(flt(amount + total_tax, 2)) + '</td>'
			+ '</tr></table>'
		);
	});
}

function fmt_cur(val) {
	return new Intl.NumberFormat('en-IN', {
		minimumFractionDigits: 2, maximumFractionDigits: 2
	}).format(val);
}

// ── Create Credit Note ────────────────────────────────────────
// Uses server-side API method to fix two issues:
// FIX 1: ignore_validate_return_items — CR ADJUST not in original invoice
// FIX 2: set_posting_time=1 — preserves posting date selected in dialog
function gj_create_credit_note(frm, values, dialog) {

	if (flt(values.credit_amount) <= 0) {
		frappe.msgprint({ title: 'Invalid Amount', message: 'Amount must be greater than zero.', indicator: 'red' });
		return;
	}

	dialog.disable_primary_action();
	frappe.show_progress('Creating Credit Note...', 20, 100);

	frappe.call({
		method: 'erpnext.accounts.doctype.sales_invoice.quick_credit_note.create_quick_credit_note',
		args: {
			return_against: values.return_against,
			posting_date:   values.posting_date,
			credit_amount:  values.credit_amount,
			reason:         values.reason
		},
		callback: function(r) {
			frappe.show_progress('', 100, 100);

			if (r.exc || !r.message) {
				d._submitting = false;
				dialog.enable_primary_action();
				frappe.msgprint({
					title: 'Error',
					message: 'Could not create Credit Note. Check console for details.',
					indicator: 'red'
				});
				return;
			}

			var cn_name = r.message;
			dialog.hide();

			frappe.show_alert({
				message: '✅ Credit Note <b>' + cn_name + '</b> created and submitted',
				indicator: 'green'
			}, 6);


		}
	});
}

