function gj_bind_tab_on_company(frm) {

    // Access the actual input element via Frappe's field dict
    // This is the correct way — not CSS selector on the DOM
    var company_field = frm.fields_dict["company"];
    if (!company_field || !company_field.$input) return;

    // Remove old listener
    company_field.$input.off("keydown.gj_tab");

    company_field.$input.on("keydown.gj_tab", function (e) {

        // Tab only, not Shift+Tab
        if (e.which !== 9 || e.shiftKey) return;

        e.preventDefault();
        e.stopPropagation();

        gj_jump_to_items(frm);
    });
}

function gj_jump_to_items(frm) {

    var grid = frm.fields_dict.items && frm.fields_dict.items.grid;
    if (!grid) return;

    // If no rows yet — add one first
    if (!frm.doc.items || frm.doc.items.length === 0) {
        grid.add_new_row();
        frm.refresh_field("items");
    }

    // Wait for row to render then focus item_code
    setTimeout(function () {
        gj_focus_first_item_code(frm);
    }, 200);
}

function gj_focus_first_item_code(frm) {

    var grid = frm.fields_dict.items && frm.fields_dict.items.grid;
    if (!grid || !grid.grid_rows || !grid.grid_rows.length) return;

    var first_row = grid.grid_rows[0];
    if (!first_row) return;

    // In Frappe v15 inline grid, cell is not an input until clicked.
    // Click the cell to activate inline edit, then focus the input.
    var $cell = $(first_row.row).find("[data-fieldname='item_code']");
    if (!$cell.length) return;

    // Click activates the inline input
    $cell.trigger("click");

    // After Frappe renders the input inside the cell, focus it
    setTimeout(function () {
        var $input = $cell.find("input");
        if ($input.length) {
            $input.focus();
            $input.select();
        }
    }, 150);
}

