function _show_upload_dialog() {
    const d = new frappe.ui.Dialog({
        title: __("Import PrintFlow Billing from Excel"),
        fields: [
            {
                fieldname: "info",
                fieldtype: "HTML",
                options: `<div class="alert alert-info" style="font-size:12px;margin-bottom:8px">
                    <b>Expected columns (same as Job Billing Report):</b><br>
                    Bill No &bull; Party &bull; Job No &bull; Description &bull; Sheets &bull;
                    Paper Size &bull; Print Size &bull; Print Type &bull; Print Charge &bull;
                    Lamination &bull; Min Charge &bull; Other Charges &bull; Other Amt &bull;
                    Status &bull; Date<br>
                    <small>Rows with Status = "Billed" are skipped automatically.</small>
                </div>`
            },
            {
                fieldname: "excel_file",
                fieldtype: "Attach",
                label: __("Excel File (.xlsx)"),
                reqd: 1,
                options: "{ \"restrictions\": { \"allowed_file_types\": [\".xlsx\"] } }"
            }
        ],
        primary_action_label: __("Upload & Import"),
        primary_action(values) {
            if (!values.excel_file) {
                frappe.msgprint(__("Please attach an Excel file first."));
                return;
            }
            d.hide();
            frappe.show_progress(__("Importing from PrintFlow"), 0, 100, __("Reading Excel file\u2026"));

            frappe.call({
                method: "erpnext.accounts.doctype.sales_invoice.gpp_import.create_from_excel",
                args: { file_url: values.excel_file },
                callback(r) {
                    frappe.hide_progress();
                    if (r.message) {
                        _show_results(r.message);
                    }
                }
            });
        }
    });
    d.show();
}

function _show_results(results) {
    const created = results.filter(r => !r.skipped);
    const skipped = results.filter(r => r.skipped);

    let html = `<div style="font-family:var(--font-stack);font-size:13px">`;

    if (created.length) {
        html += `<p><b>${created.length} record(s) imported successfully:</b></p>
        <table class="table table-bordered table-sm" style="font-size:12px">
          <thead><tr>
            <th>Bill No</th><th>Party</th><th>Job No</th><th>Sales Invoice</th>
          </tr></thead><tbody>`;
        created.forEach(r => {
            const si = r.si ? `<a href="/app/sales-invoice/${r.si}" target="_blank">${r.si}</a>` : "\u2014";
            html += `<tr>
              <td>${r.bill_no||""}</td><td>${r.party||""}</td><td>${r.job_no||""}</td>
              <td>${si}</td>
            </tr>`;
        });
        html += `</tbody></table>`;
    }

    if (skipped.length) {
        html += `<p style="margin-top:8px"><b>${skipped.length} row(s) skipped:</b></p>
        <table class="table table-bordered table-sm" style="font-size:12px">
          <thead><tr><th>Bill No</th><th>Party</th><th>Reason</th></tr></thead><tbody>`;
        skipped.forEach(r => {
            html += `<tr><td>${r.bill_no||""}</td><td>${r.party||""}</td><td>${r.reason||"\u2014"}</td></tr>`;
        });
        html += `</tbody></table>`;
    }

    html += `</div>`;

    frappe.msgprint({ title: __("Import Results"), message: html, wide: true });

    if (created.length) {
        cur_list && cur_list.refresh();
    }
}
